package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	nextInt64 := func() int64 {
		scanner.Scan()
		val, _ := strconv.ParseInt(scanner.Text(), 10, 64)
		return val
	}

	n := nextInt64()
	k := nextInt64()

	seen := make(map[int64]bool)
	ok := true

	for i := int64(1); i <= k; i++ {
		rest := n % i
		if _, exists := seen[rest]; exists {
			ok = false
			break
		}
		seen[rest] = true
	}

	if ok {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}

